head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldfil25800";
scwin.searchComTpYn = "N";

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.init_ctxDefaults();
        scwin.init_fillGen();
        await scwin.init_rowCopy();
        scwin.init_conds();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldfil25800.onpageload' });
    }
};

/**
 * @method
 * @name init_ctxDefaults
 * @description 조건 평가 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다. 진입 기본값 충전 — 파라미터로 안 온 키에 스펙 기본값(조건 평가보다 먼저).
 * @returns {void}
 * @hidden N
 */
scwin.init_ctxDefaults = function () {
    const cds = {"listCnt":"1"};
    const pc0 = $c.util.getComponent("dma_pageContext");
    if (!pc0 || !pc0.get || !pc0.set) { return; }
    for (let ck in cds) { const cv0 = pc0.get(ck); if (cv0 === undefined || cv0 === null || cv0 === '') { pc0.set(ck, cds[ck]); } }
};

// TODO Stage2: 컨텍스트 키 출처 미확인(as-is EL · 회신 A-3) — subcomList, listCnt, allCnt

/**
 * @method
 * @name init_conds
 * @description 표시 조건 평가 — 컨텍스트·세션 값에 따라 영역·버튼을 show/hide(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_conds = function () {
    const binds = [{ id: "img_116", fn: function(){ return ((dlt_subcomList.getCellData(0, "isuInstTp") ?? (() => { throw new Error("unresolved:" + "subcomList.isuInstTp"); })()) === '1'); } }, { id: "img_118", fn: function(){ return ((dlt_subcomList.getCellData(0, "isuInstTp") ?? (() => { throw new Error("unresolved:" + "subcomList.isuInstTp"); })()) === '2'); } }, { id: "img_120", fn: function(){ return ((dlt_subcomList.getCellData(0, "isuInstTp") ?? (() => { throw new Error("unresolved:" + "subcomList.isuInstTp"); })()) === '3'); } }, { id: "img_122", fn: function(){ return ((dlt_subcomList.getCellData(0, "isuInstTp") ?? (() => { throw new Error("unresolved:" + "subcomList.isuInstTp"); })()) === '4'); } }, { id: "img_124", fn: function(){ return ((dlt_subcomList.getCellData(0, "isuInstTp") ?? (() => { throw new Error("unresolved:" + "subcomList.isuInstTp"); })()) === '5'); } }, { id: "img_126", fn: function(){ return ((dlt_subcomList.getCellData(0, "isuInstTp") ?? (() => { throw new Error("unresolved:" + "subcomList.isuInstTp"); })()) === '6'); } }, { id: "ipt_comNm", fn: function(){ return ((dlt_subcomList.getCellData(0, "isuInstTp") ?? (() => { throw new Error("unresolved:" + "subcomList.isuInstTp"); })()) === '1'); } }, { id: "ipt_comNm_2", fn: function(){ return ((dlt_subcomList.getCellData(0, "isuInstTp") ?? (() => { throw new Error("unresolved:" + "subcomList.isuInstTp"); })()) === '2'); } }, { id: "ipt_comNm_3", fn: function(){ return ((dlt_subcomList.getCellData(0, "isuInstTp") ?? (() => { throw new Error("unresolved:" + "subcomList.isuInstTp"); })()) === '3'); } }, { id: "ipt_comNm_4", fn: function(){ return ((dlt_subcomList.getCellData(0, "isuInstTp") ?? (() => { throw new Error("unresolved:" + "subcomList.isuInstTp"); })()) === '4'); } }, { id: "ipt_comNm_5", fn: function(){ return ((dlt_subcomList.getCellData(0, "isuInstTp") ?? (() => { throw new Error("unresolved:" + "subcomList.isuInstTp"); })()) === '5'); } }, { id: "ipt_comNm_6", fn: function(){ return ((dlt_subcomList.getCellData(0, "isuInstTp") ?? (() => { throw new Error("unresolved:" + "subcomList.isuInstTp"); })()) === '6'); } }, { id: "c_when_107", fn: function(){ return (!(String(((dma_pageContext.get("subcomList") ?? "")) == null ? '' : ((dma_pageContext.get("subcomList") ?? ""))).length === 0)); } }, { id: "tr_111", fn: function(){ return (!(String(((dma_pageContext.get("subcomList") ?? "")) == null ? '' : ((dma_pageContext.get("subcomList") ?? ""))).length === 0)); } }, { id: "c_otherwise_149", fn: function(){ return (!((!(String(((dma_pageContext.get("subcomList") ?? "")) == null ? '' : ((dma_pageContext.get("subcomList") ?? ""))).length === 0)))); } }];
    binds.forEach(function (b) {
        const comp = $c.util.getComponent(b.id);
        if (!comp) { return; }
        let ok;
        // 조건식이 미해결 값(unresolved throw)을 읽는 자리는 그 바인드만 건너뛴다 — 공급사 산출의 바인드별 격리 유지
        try { ok = !!b.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "conds:" + b.id }); return; }
        if (ok) { comp.show(); } else { comp.hide(); }
        if (ok && b.grids) {
            b.grids.forEach(function (gid) {
                const gc = $c.util.getComponent(gid);
                if (gc && gc.refreshGridView) { gc.refreshGridView(); }
            });
        }
    });
};

/**
 * @method
 * @name init_fillGen
 * @description 제너레이터 채움 — 진입점(onpageload)에서 순차 실행.
 * @param {String} boxId boxId
 * @returns {void}
 * @hidden N
 */
scwin.init_fillGen = function (boxId) {
    // 채우지 못한 자리를 모은다(동작은 계속 — 화면은 종전과 같다).
    const genSkip = [];
    let genCleared = 0;
    const genFills = [{ genId: "c_foreach_110", entity: "dlt_subcomList", countIds: [], cells: [{ childId: "__rc1", fn: function (v, i) { return String(i + 1); } }, { childId: "ipt_comNm", fn: function (v, i) { return String(v("subcomNm")); } }, { childId: "ipt_comNm_2", fn: function (v, i) { return String(v("subcomNm")); } }, { childId: "ipt_comNm_3", fn: function (v, i) { return String(v("subcomNm")); } }, { childId: "ipt_comNm_4", fn: function (v, i) { return String(v("subcomNm")); } }, { childId: "ipt_comNm_5", fn: function (v, i) { return String(v("subcomNm")); } }, { childId: "ipt_comNm_6", fn: function (v, i) { return String(v("subcomNm")); } }] }];
    const gf = genFills;
    for (let g = 0; g < gf.length; g++) {
        const f = gf[g];
        if (boxId && f.entity !== boxId) { continue; }
        const gen = $c.util.getComponent(f.genId);
        const ds = $c.util.getComponent(f.entity);
        if (!gen || !ds || !ds.getTotalRow) { genSkip.push({ gen: f.genId, box: f.entity, why: !gen ? 'no-generator' : 'no-box' }); continue; }
        const n = ds.getRowCount();
        if (!n) { genSkip.push({ gen: f.genId, box: f.entity, why: 'empty-box' }); continue; }
        // 멱등 — 이미 채워진 제너레이터는 건너뛴다(플래그 없이 컴포넌트 상태로 판단).
        //   단, 상자를 지정해 «다시 그리라» 고 부른 경우(데이터가 새로 담긴 때)는 비우고 다시 채운다.
        if (gen.getLength && gen.getLength() > 0) {
            if (!boxId) { continue; }
            const had = gen.getLength();
            while (gen.getLength() > 0) { gen.removeChild(); }
            genCleared += had;
        }
        let row = 0;
        const cell = function (col) { const v = ds.getCellData(row, col); return (v === undefined || v === null) ? '' : v; };
        for (let i = 0; i < n; i++) {
            row = i;
            gen.insertChild(i);
            for (let c = 0; c < f.cells.length; c++) {
                const ch = gen.getChild(i, f.cells[c].childId);
                if (!ch || !ch.setValue) { continue; }
                ch.setValue(f.cells[c].fn(cell, i));
            }
            for (let k = 0; k < f.countIds.length; k++) {
                const cn = gen.getChild(i, f.countIds[k]);
                if (cn && cn.setValue) { cn.setValue(String(i + 1)); }
            }
            // 행 조건 — 마지막 행에만 보이는 자리.
            if (f.rowConds) {
                for (let rc = 0; rc < f.rowConds.length; rc++) {
                    const rn = gen.getChild(i, f.rowConds[rc].childId);
                    if (!rn) { continue; }
                    const show = (f.rowConds[rc].kind === 'last') ? (i === n - 1) : true;
                    if (rn.setStyle) { rn.setStyle('display', show ? '' : 'none'); }
                }
            }
        }
    }
    if (genSkip.length) {
        // 우리 계측이 읽는 자리 — 화면 동작에는 영향이 없다.
        scwin.genFillSkipped = genSkip;
    }
    if (genCleared) { scwin.genFillCleared = (scwin.genFillCleared || 0) + genCleared; }
};

/**
 * @method
 * @name init_rowCopy
 * @description dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_rowCopy = async function () {
    const rows = [{ childId: "__rb0", fn: function () { return String((($c.session && $c.session.getUserInfo && $c.session.getUserInfo()) || {})["comAbbrv"] ?? ""); } }];
    let copied = 0;
    for (let i = 0; i < rows.length; i++) {
        const it = rows[i];
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { /* TODO Stage2: [sdd] 행 복사 대상 부재:  it.childId */ continue; }
        try {
            const v = it.fn();
            if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); copied++; }
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); }
    }
    return copied;
};

// [A] 초기 목록 미해결 — 진입 키 subcom 를 쓰는 tx 가 4개다(tx_fn_bascomInfoModify, tx_fn_register, tx_fn_subInfoModify, tx_fn_subInfoDelete)

