/**
 * @method
 * @name bascomInfoModify
 * @description bascom Info Modify 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.bascomInfoModify = async function () {
    if (await $c.win.confirm("모회사 정보를 수정하시겠습니까?")) {
        const basForm = (document.bascomForm || { elements: [] });
        const subForm = (document.subcomForm || { elements: [] });
        $c.util.getComponent("slc_lgscaleCorpYn").setValue($c.util.getComponent("dma_bascomInfoModifyReq").get("lgscaleCorpYn"));
        $c.util.getComponent("slc_parntcomKindTpCd").setValue($c.util.getComponent("dma_bascomInfoModifyReq").get("parntcomKindTpCd"));
        basForm.action = '/account/subcom.do';
        $c.util.getComponent('dma_bascomInfoModifyReq').set('method', 'modifyBascomInfo');
        await scwin.tx_fn_bascomInfoModify();
    }
};

/**
 * @method
 * @name findCompany
 * @description find Company 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.findCompany = async function () {
    const corpSearchURL = '/jldfil00033/jldfil00033.xml';
    // TODO Stage2: 전환 미완(공급사 드러냄 — 사유 알림 유지) "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — "
