/**
 * @method
 * @name searchSubCom
 * @description search Sub Com 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.searchSubCom = async function () {
    const subForm = (document.subcomForm || { elements: [] });
    if (($c.util.getComponent('slc_searchComTp').getValue() == null ? '' : String($c.util.getComponent('slc_searchComTp').getValue())) === '') {
        await $c.win.alert("발행기관 등록여부를 선택하시고 『신규등록』버튼을 클릭하세요.");
        return;
    } else {
        if ($c.util.getComponent('slc_searchComTp').getValue()=== '1') {
            ($c.util.getComponent("registLayer") && $c.util.getComponent("registLayer").show ? $c.util.getComponent("registLayer").show() : console.warn('[sdd] show 대상 미해결: ' + "registLayer"));
            $c.util.getComponent("ipt_regComNm").readOnly = 'true';
            ($c.util.getComponent("btnLayer") && $c.util.getComponent("btnLayer").show ? $c.util.getComponent("btnLayer").show() : console.warn('[sdd] show 대상 미해결: ' + "btnLayer"));
            ($c.util.getComponent("strLayer") && $c.util.getComponent("strLayer").hide ? $c.util.getComponent("strLayer").hide() : console.warn('[sdd] hide 대상 미해결: ' + "strLayer"));
            $c.util.getComponent('ipt_regComNm').readonly = 'true';
            scwin.searchComTpYn = "N";
        } else {
            if ($c.util.getComponent('slc_searchComTp').getValue()=== '2') {
                ($c.util.getComponent("registLayer") && $c.util.getComponent("registLayer").show ? $c.util.getComponent("registLayer").show() : console.warn('[sdd] show 대상 미해결: ' + "registLayer"));
                $c.util.getComponent("ipt_regComNm").readOnly = '';
                ($c.util.getComponent("btnLayer") && $c.util.getComponent("btnLayer").hide ? $c.util.getComponent("btnLayer").hide() : console.warn('[sdd] hide 대상 미해결: ' + "btnLayer"));
                ($c.util.getComponent("strLayer") && $c.util.getComponent("strLayer").show ? $c.util.getComponent("strLayer").show() : console.warn('[sdd] show 대상 미해결: ' + "strLayer"));
                scwin.searchComTpYn = "Y";
            }
        }
    }
};

/**
 * @method
 * @name register
 * @description register 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.register = async function () {
    const subForm = (document.subcomForm || { elements: [] });
    if (scwin.searchComTpYn === 'Y') {
        if (!scwin.chk_korean($c.util.getComponent('ipt_regComNm'))) {
            await $c.win.alert("회사명을 한글로 입력하십시오.");
            $c.util.getComponent("ipt_regComNm").setValue("");
            $c.util.getComponent("ipt_regComNm").focus();
            return;
        }
    }
    $c.util.getComponent('dma_bascomInfoModifyReq').set('subcomNm', $c.util.getComponent('ipt_regComNm').getValue());
    $c.util.getComponent('dma_bascomInfoModifyReq').set('reltIsurCd', $c.util.getComponent("dma_bascomInfoModifyReq").get("regIsurCd"));
    $c.util.getComponent('dma_bascomInfoModifyReq').set('isurRelTpCd', $c.util.getComponent('slc_regIsurRelTpCd').getValue());
    $c.util.getComponent('dma_bascomInfoModifyReq').set('subcomAsstTotamtTpCd', $c.util.getComponent('slc_regSubTpCd').getValue());
    subForm.action = '/account/subcom.do';
    $c.util.getComponent('dma_bascomInfoModifyReq').set('method', 'registSubcomInfo');
    await scwin.tx_fn_register();
};

/**
 * @method
 * @name subInfoModify
 * @description sub Info Modify 처리
 * @param {*} rowNum rowNum
 * @param {String} isuInstTp isuInstTp
 * @param {String} subcomNm subcomNm
 * @param {String} reltIsurCd reltIsurCd
 * @param {String} isurRelTpCd isurRelTpCd
 * @param {String} strtDd strtDd
 * @param {String} endDd endDd
 * @param {*} allCnt allCnt
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.subInfoModify = async function (rowNum, isuInstTp, subcomNm, reltIsurCd, isurRelTpCd, strtDd, endDd, allCnt) {
    if (await $c.win.confirm("『" + subcomNm + "』의 정보를 수정하시겠습니까?")) {
        const subForm = (document.subcomForm || { elements: [] });
        $c.util.getComponent('dma_bascomInfoModifyReq').set('reltIsurCd', reltIsurCd);
        $c.util.getComponent('dma_bascomInfoModifyReq').set('isurRelTpCd', isurRelTpCd);
        $c.util.getComponent('dma_bascomInfoModifyReq').set('strtDd', strtDd);
        $c.util.getComponent('dma_bascomInfoModifyReq').set('endDd', endDd);
        if (allCnt === 1) {
            $c.util.getComponent('dma_bascomInfoModifyReq').set('subcomNm', $c.util.getComponent('dlt_subcomList').getCellData(0, 'subcomNm'));
            $c.util.getComponent('dma_bascomInfoModifyReq').set('subcomAsstTotamtTpCd', $c.util.getComponent('slc_subTpCd').getValue());
        } else {
            $c.util.getComponent('dma_bascomInfoModifyReq').set('subcomNm', $c.util.getComponent('dlt_subcomList').getCellData(rowNum-1, 'subcomNm'));
            $c.util.getComponent('dma_bascomInfoModifyReq').set('subcomAsstTotamtTpCd', $c.util.getComponent('slc_subTpCd')[rowNum-1].value);
        }
        if (isuInstTp === '1') {
            if (!scwin.chk_korean(subForm.subcomNm)) {
                await $c.win.alert("회사명을 한글로 입력하십시오.");
                /* TODO Stage2: [sdd] 미실현 동작: set_focus (대상 미해석) — 전환 미완 */ /* unresolved-target intent:set_focus — {target}.focus({args}) */
                return;
            }
        }
        subForm.action = '/account/subcom.do';
        $c.util.getComponent('dma_bascomInfoModifyReq').set('method', 'modifySubcomInfo');
        await scwin.tx_fn_subInfoModify();
    }
};

